    while (t < text.len) {
        if (p < pattern.len and pattern[p] == '*') { star = p; p += 1; retry = t; continue; }
        if (p < pattern.len) {
            if (pattern[p] == '?' or pattern[p] == text[t]) { p += 1; t += 1; continue; }
            if (pattern[p] == '[') {
                if (std.mem.indexOfScalarPos(u8, pattern, p + 1, ']')) |end| {
                    var idx = p + 1; const negate = idx < end and (pattern[idx] == '!' or pattern[idx] == '^');
