                    while (idx < end) {
                        if (idx + 2 < end and pattern[idx + 1] == '-') { if (text[t] >= pattern[idx] and text[t] <= pattern[idx + 2]) matches = true; idx += 3; }
                        else { if (pattern[idx] == text[t]) matches = true; idx += 1; }
                    }
